// ============================================
// Page Flow Section Component
// For page-by-page flow sections with image + content
// ============================================

import * as React from 'react';
import { cn } from '@/lib/utils';

interface PageFlowSectionProps {
  direction: 'left' | 'right';
  image: {
    src: string;
    alt: string;
    width?: number | string;
    height?: number | string;
  };
  title: string;
  intent: string;
  objective: string;
  keyActions: string[];
  additionalContent?: React.ReactNode;
  className?: string;
}

export function PageFlowSection({
  direction,
  image,
  title,
  intent,
  objective,
  keyActions,
  additionalContent,
  className,
}: PageFlowSectionProps) {
  const imageWidth = image.width ?? 493;
  const imageHeight = image.height ?? 298;
  // Data-driven aspect ratio keeps the declared 493x298 proportions on desktop
  // while the width stays fluid below lg. A fixed pixel width here pushed the
  // row 314px sideways at 375 because the image was `shrink-0`.
  const hasFixedSize =
    typeof imageWidth === 'number' && typeof imageHeight === 'number';

  return (
    <div
      className={cn(
        'flex flex-col gap-10 lg:flex-row lg:items-center',
        direction === 'right' && 'lg:flex-row-reverse',
        className
      )}
    >
      {/* Image */}
      <div
        className="w-full max-w-full overflow-hidden lg:shrink-0"
        style={{
          maxWidth: imageWidth,
          aspectRatio: hasFixedSize
            ? `${imageWidth} / ${imageHeight}`
            : undefined,
        }}
      >
        <img
          src={image.src}
          alt={image.alt}
          className="w-full h-full object-cover"
        />
      </div>

      {/* Content */}
      <div className="flex-1 min-w-0 flex flex-col gap-2.5">
        <h3 className="font-body text-2xl font-extrabold text-foreground">
          {title}
        </h3>
        <div className="space-y-1 font-body text-sm leading-normal text-muted-foreground">
          <p>
            <span className="font-bold">Intent:</span>{' '}
            <span className="font-normal">{intent}</span>
          </p>
          <p>
            <span className="font-bold">Objective:</span>{' '}
            <span className="font-normal">{objective}</span>
          </p>
          <p className="font-bold mt-2">Key Actions:</p>
          <ul className="list-disc ml-5 space-y-1">
            {keyActions.map((action, index) => (
              <li key={index} className="font-normal">
                {action}
              </li>
            ))}
          </ul>
          {additionalContent && (
            <div className="mt-4">{additionalContent}</div>
          )}
        </div>
      </div>
    </div>
  );
}

// ============================================
// Page Flow with Split Text Layout
// For sections with image and two-column text
// ============================================

interface PageFlowSplitProps {
  image: {
    src: string;
    alt: string;
    width?: number | string;
    height?: number | string;
  };
  leftContent: {
    title: string;
    intent: string;
    objective: string;
    keyActions: string[];
  };
  rightContent: React.ReactNode;
  className?: string;
}

export function PageFlowSplit({
  image,
  leftContent,
  rightContent,
  className,
}: PageFlowSplitProps) {
  return (
    <div className={cn('flex flex-col gap-5', className)}>
      {/* Split Content Row */}
      <div className="flex flex-col gap-5 py-5 lg:flex-row lg:items-center lg:justify-between">
        <div className="flex-1 min-w-0 flex flex-col gap-2.5 lg:pr-8">
          <h3 className="font-body text-2xl font-extrabold text-foreground">
            {leftContent.title}
          </h3>
          <div className="space-y-1 font-body text-sm leading-normal text-muted-foreground">
            <p>
              <span className="font-bold">Intent:</span>{' '}
              <span className="font-normal">{leftContent.intent}</span>
            </p>
            <p>
              <span className="font-bold">Objective:</span>{' '}
              <span className="font-normal">{leftContent.objective}</span>
            </p>
            <p className="font-bold mt-2">Key Actions:</p>
            <ul className="list-disc ml-5 space-y-1">
              {leftContent.keyActions.map((action, index) => (
                <li key={index} className="font-normal">
                  {action}
                </li>
              ))}
            </ul>
          </div>
        </div>

        {/* Right Box */}
        <div className="w-full max-w-full overflow-hidden rounded-sm border border-border bg-card/40 p-[30px] lg:w-[538px] lg:shrink-0">
          <div className="font-body text-sm leading-normal text-muted-foreground">
            {rightContent}
          </div>
        </div>
      </div>

      {/* Full Width Image */}
      <div
        className="w-full max-w-full overflow-hidden"
        style={{ maxWidth: image.width ?? '100%' }}
      >
        <img
          src={image.src}
          alt={image.alt}
          className="w-full h-auto object-cover"
        />
      </div>
    </div>
  );
}
